  const meta = resolveStory(storyId);
  if (meta === null) {
    throw new Error(`host_run: unknown story "${storyId}" (not found in the configured story store); refuse pre-spawn`);
  }
  return meta.phase && meta.phase.length > 0 ? meta.phase : 'adhoc';
}

